package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("zoryasTomeStacks")
public interface ZoryasTomeConfig extends Config
{
    enum TimerUnit { TICKS, SECONDS }

    @ConfigItem(keyName = "showTimer", name = "Show inventory timer",
        description = "Show a countdown on the tome in your inventory")
    default boolean showTimer()
    {
        return true;
    }

    @ConfigItem(keyName = "timerUnit", name = "Timer unit",
        description = "Display the countdown in game ticks or seconds")
    default TimerUnit timerUnit()
    {
        return TimerUnit.TICKS;
    }
}

package com.example;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

public class ZoryasTomeItemOverlay extends WidgetItemOverlay
{
    private static final Color TEXT_COLOR = Color.WHITE;
    private final ZoryasTomePlugin plugin;
    private final ZoryasTomeConfig config;

    @Inject
    ZoryasTomeItemOverlay(ZoryasTomePlugin plugin, ZoryasTomeConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        showOnInventory();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item)
    {
        if (itemId != ZoryasTomePlugin.CHARGED_TOME_ITEM_ID || plugin.getStacks() <= 0)
        {
            return;
        }

        Rectangle bounds = item.getCanvasBounds();
        TextComponent count = new TextComponent();
        count.setText(Integer.toString(plugin.getStacks()));
        count.setColor(TEXT_COLOR);
        count.setPosition(new Point(bounds.x + 2, bounds.y + 12));
        count.render(graphics);

        if (config.showTimer() && plugin.getTicksRemaining() > 0)
        {
            String timer = config.timerUnit() == ZoryasTomeConfig.TimerUnit.TICKS
                ? Integer.toString(plugin.getTicksRemaining())
                : Integer.toString((plugin.getTicksRemaining() * 3 + 4) / 5);
            TextComponent countdown = new TextComponent();
            countdown.setText(timer);
            countdown.setColor(TEXT_COLOR);
            int width = graphics.getFontMetrics().stringWidth(timer);
            countdown.setPosition(new Point(bounds.x + bounds.width - width - 2,
                bounds.y + bounds.height - 2));
            countdown.render(graphics);
        }
    }
}

package com.example;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.Counter;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@PluginDescriptor(
	name = "Zorya's Tome Stacks",
	description = "Shows remaining Zorya's Tome stacks",
	tags = "book"
)
public class ZoryasTomePlugin extends Plugin
{
    private static final int STACKS_VARP = 5926;
    private static final int TIMER_TICKS = 50;
    static final int CHARGED_TOME_ITEM_ID = 34725;

    @Inject private Client client;
    @Inject private ItemManager itemManager;
    @Inject private InfoBoxManager infoBoxManager;
    @Inject private OverlayManager overlayManager;
    @Inject private ZoryasTomeItemOverlay itemOverlay;

    private Counter stackCounter;
    private int stacks;
    private int ticksRemaining;

    @Provides
    ZoryasTomeConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ZoryasTomeConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(itemOverlay);
        updateStacks(false);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(itemOverlay);
        removeCounter();
        stacks = 0;
        ticksRemaining = 0;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (event.getVarpId() == STACKS_VARP)
        {
            updateStacks(true);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (ticksRemaining > 0)
        {
            ticksRemaining--;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            updateStacks(false);
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            removeCounter();
            stacks = 0;
            ticksRemaining = 0;
        }
    }

    int getStacks()
    {
        return stacks;
    }

    int getTicksRemaining()
    {
        return ticksRemaining;
    }

    private void updateStacks(boolean varpChanged)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        int newStacks = client.getVarpValue(STACKS_VARP);
        if (newStacks != stacks && varpChanged && newStacks > 0)
        {
            ticksRemaining = TIMER_TICKS;
        }
        stacks = newStacks;
        if (stacks <= 0)
        {
            ticksRemaining = 0;
            removeCounter();
            return;
        }

        if (stackCounter == null)
        {
            stackCounter = new Counter(itemManager.getImage(CHARGED_TOME_ITEM_ID), this, stacks);
            stackCounter.setTooltip("Zorya's Tome stacks");
            infoBoxManager.addInfoBox(stackCounter);
        }
        else
        {
            stackCounter.setCount(stacks);
        }
    }

    private void removeCounter()
    {
        if (stackCounter != null)
        {
            infoBoxManager.removeInfoBox(stackCounter);
            stackCounter = null;
        }
    }
}

package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ZoryasTomePlugin.class);
		RuneLite.main(args);
	}
}
